#!/usr/bin/env node
'use strict';

/*
 * Research-only money-management simulation on the exact accepted six-strategy ledger.
 * Start balance $1000, base XAUUSD lot 0.01.
 * After each losing CLOSED trade: double lot. After any winning CLOSED trade: reset to 0.01.
 * Portfolio entries/exits remain exactly those generated by canonical MAX OPEN=2 engine.
 * Assumption for XAUUSD: 1.00 lot = $100 P/L per $1 gold move, therefore 0.01 lot = $1 per $1 move.
 */
const {spawnSync}=require('child_process');const fs=require('fs');const os=require('os');const path=require('path');
const FROM=process.argv[2]||'2023-08-29',TO=process.argv[3]||'2026-08-29';const START=1000,BASE=.01;
const root=path.resolve(__dirname,'..'),engine=path.join(__dirname,'backtest-live-gold-portfolio-6-exact.js'),ledger=path.join(os.tmpdir(),`mg-${process.pid}.json`),tmp=path.join(__dirname,`.tmp-mg-${process.pid}.js`);
let src=fs.readFileSync(engine,'utf8');const marker="console.log('\\n🔒 Research only. Live strategies/VIP routing untouched.');";if(!src.includes(marker))throw new Error('Exact engine marker missing');src=src.replace(marker,`require('fs').writeFileSync(process.env.BACKTEST_LEDGER_JSON,JSON.stringify({accepted,rejected},null,2));`+marker);fs.writeFileSync(tmp,src);
let r;try{r=spawnSync(process.execPath,[tmp,FROM,TO],{cwd:root,stdio:'inherit',env:{...process.env,BACKTEST_LEDGER_JSON:ledger}})}finally{try{fs.unlinkSync(tmp)}catch{}}if(r?.status!==0||!fs.existsSync(ledger))process.exit(r?.status||1);const d=JSON.parse(fs.readFileSync(ledger));try{fs.unlinkSync(ledger)}catch{}
const t=[...(d.accepted||[])].sort((a,b)=>(a.exitTime-b.exitTime)||(a.time-b.time));let bal=START,peak=START,maxDD=0,maxDDPct=0,lot=BASE,maxLot=BASE,streak=0,maxStreak=0,w=0,l=0,ruin=false,ruinAt=null,totalProfit=0,totalLoss=0;
const yearly={};
for(let i=0;i<t.length;i++){const x=t[i];const y=new Date(x.exitTime||x.time).getUTCFullYear();if(!yearly[y])yearly[y]={start:bal,end:bal,n:0,pnl:0,maxLot:lot};
 // Convert canonical trade R back to its actual gold-dollar move using risk distance when available.
 // Fallback: R * |entry-stop|. For exact ledgers entry/stop are present.
 const riskDist=Math.abs(Number(x.entry)-Number(x.stop));const goldMove=Number.isFinite(riskDist)&&riskDist>0?Number(x.r)*riskDist:Number(x.r);
 const pnl=goldMove*(lot*100);bal+=pnl;yearly[y].n++;yearly[y].pnl+=pnl;yearly[y].end=bal;yearly[y].maxLot=Math.max(yearly[y].maxLot,lot);
 if(pnl>0){w++;totalProfit+=pnl;lot=BASE;streak=0}else{l++;totalLoss+=-pnl;streak++;maxStreak=Math.max(maxStreak,streak);lot*=2;maxLot=Math.max(maxLot,lot)}
 peak=Math.max(peak,bal);const dd=peak-bal;maxDD=Math.max(maxDD,dd);maxDDPct=Math.max(maxDDPct,peak?dd/peak*100:0);
 if(bal<=0&&!ruin){ruin=true;ruinAt={i:i+1,date:new Date(x.exitTime||x.time).toISOString(),balance:bal,nextLot:lot,strategy:x.strategy,side:x.side};break}
}
console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');console.log('💰 LOSS-DOUBLING BACKTEST — EXACT PORTFOLIO');console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');console.log(`📅 ${FROM} → ${TO}`);console.log(`💵 Start: $${START.toFixed(2)} | Base lot: ${BASE.toFixed(2)}`);console.log('📈 Loss => next lot ×2 | Win => reset 0.01');console.log('⚠️ No broker margin/lot cap/slippage/commission modeled');console.log(`\nTrades processed: ${w+l}/${t.length} | Wins ${w} | Losses ${l}`);console.log(`Ending balance: $${bal.toFixed(2)}`);console.log(`Net P/L: ${(bal-START)>=0?'+':''}$${(bal-START).toFixed(2)}`);console.log(`Max lot reached: ${maxLot.toFixed(2)}`);console.log(`Max losing streak: ${maxStreak}`);console.log(`Max equity DD: $${maxDD.toFixed(2)} (${maxDDPct.toFixed(2)}%)`);console.log(`Money PF: ${totalLoss?(totalProfit/totalLoss).toFixed(2):'∞'}`);console.log(`Account blown: ${ruin?'YES ❌':'NO ✅'}`);if(ruin)console.log(`💥 Ruin trade #${ruinAt.i} | ${ruinAt.date} | balance $${ruinAt.balance.toFixed(2)} | next lot ${ruinAt.nextLot.toFixed(2)} | ${ruinAt.strategy} ${ruinAt.side}`);
console.log('\n📅 YEARLY MONEY CURVE');for(const [y,z] of Object.entries(yearly))console.log(`${y} | ${z.n} trades | Start $${z.start.toFixed(2)} | P/L ${z.pnl>=0?'+':''}$${z.pnl.toFixed(2)} | End $${z.end.toFixed(2)} | MaxLot ${z.maxLot.toFixed(2)}`);console.log('\n🔒 Research only. Live strategies/VIP routing untouched.');